index 51be0c4..e7a93d1 100644
--- a/src/compare.js
+++ b/src/compare.js
@@ -1,10 +1,33 @@
 import { parse } from './parse.js';

+const MAIN = ['major', 'minor', 'patch'];
+
+function compareIdentifiers(a, b) {
+  const an = /^\d+$/.test(a);
+  const bn = /^\d+$/.test(b);
+  if (an && bn) return Math.sign(Number(a) - Number(b));
+  if (an !== bn) return an ? -1 : 1;
+  return a < b ? -1 : a > b ? 1 : 0;
+}
+
+// A version without a prerelease tag ranks above any prerelease of the same core.
+export function comparePrerelease(a, b) {
+  if (!a.length || !b.length) return a.length === b.length ? 0 : a.length ? -1 : 1;
+  for (let i = 0; i < Math.max(a.length, b.length); i++) {
+    if (a[i] === undefined) return -1;
+    if (b[i] === undefined) return 1;
+    const c = compareIdentifiers(a[i], b[i]);
+    if (c !== 0) return c;
+  }
+  return 0;
+}
+
 export function compare(a, b) {
   const x = parse(a);
   const y = parse(b);
-  for (const key of ['major', 'minor', 'patch']) {
+  for (let i = 0; i < MAIN.length - 1; i++) {
+    const key = MAIN[i];
     if (x[key] !== y[key]) return x[key] < y[key] ? -1 : 1;
   }
-  return 0;
+  return comparePrerelease(x.prerelease, y.prerelease);
 }
