 export function satisfies(version, range) {
   const r = range.trim();
   const v = parse(version);
+  // Like npm semver: a prerelease only matches a range that names the same
+  // major.minor.patch with a prerelease of its own (e.g. ^1.2.0-beta.1).
+  if (v.prerelease.length > 0 && !optsIntoPrerelease(r, v)) return false;
   if (r.startsWith('^')) {
     const lo = parse(r.slice(1));
