@@ -15,4 +18,9 @@ export function satisfies(version, range) {
   if (r.startsWith('>=')) return compare(version, r.slice(2)) >= 0;
   if (r.startsWith('<')) return compare(version, r.slice(1)) < 0;
   return compare(version, r) === 0;
 }
+
+function optsIntoPrerelease(range, v) {
+  const m = /(\d+)\.(\d+)\.(\d+)-/.exec(range);
+  return m !== null && Number(m[1]) === v.major && Number(m[2]) === v.minor && Number(m[3]) === v.patch;
+}

