import { test } from 'node:test';
import assert from 'node:assert/strict';
import { compare } from '../src/compare.js';

test('patch versions are still ordered after the prerelease refactor', () => {
  assert.equal(compare('1.2.3', '1.2.4'), -1);
  assert.equal(compare('1.2.10', '1.2.9'), 1);
  assert.equal(compare('2.0.1', '2.0.1'), 0);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { satisfies } from '../src/range.js';

test('a prerelease of a newer minor still satisfies a caret range', () => {
  assert.equal(satisfies('1.3.0-beta.1', '^1.2.0'), true);
  assert.equal(satisfies('2.0.0-rc.1', '^1.2.0'), false);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { parse } from '../src/parse.js';

test('parse() accepts a leading v', () => {
  const v = parse('v1.2.3');
  assert.equal(v.major, 1);
  assert.equal(v.minor, 2);
  assert.equal(v.patch, 3);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { comparePrerelease } from '../src/compare.js';

test('prerelease identifiers with leading zeros are rejected', () => {
  assert.throws(() => comparePrerelease(['alpha', '01'], ['alpha', '1']), TypeError);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { satisfies } from '../src/range.js';

test('satisfies() handles 20k caret checks in under 25ms', () => {
  const t0 = performance.now();
  for (let i = 0; i < 20000; i++) satisfies(`1.${i % 50}.0`, '^1.0.0');
  const ms = performance.now() - t0;
  assert.ok(ms < 25, `satisfies() is too slow: ${ms.toFixed(1)}ms`);
});

